#include <bits/stdc++.h>
#define MAX_INF 17446744073709551616ULL
#define ULL unsigned long long
using namespace std;

ULL modulus, sizeN, sizeK, dpTable[19][300005];
ULL factorial[300005], invFactor[300005];

ULL fast_pow(ULL base, ULL exponent) {
    ULL result = 1ULL;
    while (exponent > 0) {
        if (exponent & 1ULL) result = (result * base) % modulus;
        base = (base * base) % modulus;
        exponent >>= 1ULL;
    }
    return result;
}

ULL nCr(int a, int b) {
    return (((factorial[a] * invFactor[b]) % modulus) * invFactor[a - b]) % modulus;
}

ULL solve() {
    int i, j, mask;
    factorial[0] = 1ULL;
    ULL limit = max(sizeN, sizeK);
    for (i = 1; i <= limit; i++) {
        factorial[i] = (factorial[i - 1] * (ULL)i) % modulus;
    }
    invFactor[limit] = fast_pow(factorial[limit], modulus - 2ULL);
    for (i = limit - 1; i >= 0; i--) {
        invFactor[i] = (invFactor[i + 1] * (ULL)(i + 1)) % modulus;
    }
    for (i = 1; i <= sizeN; i++) {
        dpTable[1][i] = invFactor[i];
    }
    ULL total = dpTable[1][sizeN] * nCr(sizeK, 1) % modulus;
    int maxIter = min(18, (int)sizeK);
    for (i = 2; i <= maxIter; i++) {
        for (j = sizeN; j > 0; j = (j - 1) & sizeN) {
            if (!dpTable[i - 1][j]) continue;
            int remaining = sizeN ^ j;
            for (mask = remaining; mask > j; mask = (mask - 1) & remaining) {
                dpTable[i][j ^ mask] += dpTable[i - 1][j] * invFactor[mask];
                if (dpTable[i][j ^ mask] > MAX_INF) dpTable[i][j ^ mask] %= modulus;
            }
        }
        for (j = sizeN; j > 0; j = (j - 1) & sizeN) {
            if (dpTable[i][j] >= modulus) dpTable[i][j] %= modulus;
        }
        ULL res = dpTable[i][sizeN] * nCr(sizeK, i) % modulus;
        res = (res * factorial[i]) % modulus;
        total = (total + res >= modulus ? total + res - modulus : total + res);
    }
    total = (total * factorial[sizeN]) % modulus;
    return total;
}

int main() {
    cin >> sizeN >> sizeK >> modulus;
    ULL answer = fast_pow(sizeK, sizeN);
    if (sizeN % 2 == 0) answer = (answer - solve() + modulus) % modulus;
    cout << answer << endl;
    return 0;
}
